selector_to_html = {"a[href=\"#docker-images-recommended\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Docker Images (Recommended)<a class=\"headerlink\" href=\"#docker-images-recommended\" title=\"Link to this heading\">#</a></h2><p>Pre-built Docker images are available for each platform:</p>", "a[href=\"#metax\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">MetaX<a class=\"headerlink\" href=\"#metax\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#install-flaggems-optional\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2. Install FlagGems (Optional)<a class=\"headerlink\" href=\"#install-flaggems-optional\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#install-from-source\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Install from Source<a class=\"headerlink\" href=\"#install-from-source\" title=\"Link to this heading\">#</a></h2><h3>Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">#</a></h3><p>Ensure you have the required software dependencies installed. See <a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">Requirements</span></a> for details.</p>", "a[href=\"#install-transformerengine-fl-megatron-lm-fl-optional\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">4. Install TransformerEngine-FL / Megatron-LM-FL (Optional)<a class=\"headerlink\" href=\"#install-transformerengine-fl-megatron-lm-fl-optional\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#install-flagcx-required\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1. Install FlagCX (Required)<a class=\"headerlink\" href=\"#install-flagcx-required\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#install-vllm-plugin-fl-optional\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3. Install vllm-plugin-FL (Optional)<a class=\"headerlink\" href=\"#install-vllm-plugin-fl-optional\" title=\"Link to this heading\">#</a></h3>", "a[href=\"requirements.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Requirements<a class=\"headerlink\" href=\"#requirements\" title=\"Link to this heading\">#</a></h1><h2>Supported Hardwares<a class=\"headerlink\" href=\"#supported-hardwares\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../user_guide/e2e-use-case.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">End-to-End Use Case: GRPO Training with verl-FL<a class=\"headerlink\" href=\"#end-to-end-use-case-grpo-training-with-verl-fl\" title=\"Link to this heading\">#</a></h1><p>This guide provides step-by-step instructions for running end-to-end GRPO training of Qwen3-0.6B on the GSM8K dataset across different hardware platforms using verl-FL.</p>", "a[href=\"#quick-setup\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Quick Setup<a class=\"headerlink\" href=\"#quick-setup\" title=\"Link to this heading\">#</a></h1><h2>Docker Images (Recommended)<a class=\"headerlink\" href=\"#docker-images-recommended\" title=\"Link to this heading\">#</a></h2><p>Pre-built Docker images are available for each platform:</p>", "a[href=\"#prerequisites\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Prerequisites<a class=\"headerlink\" href=\"#prerequisites\" title=\"Link to this heading\">#</a></h3><p>Ensure you have the required software dependencies installed. See <a class=\"reference internal\" href=\"requirements.html\"><span class=\"std std-doc\">Requirements</span></a> for details.</p>", "a[href=\"#install-verl-fl\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5. Install verl-FL<a class=\"headerlink\" href=\"#install-verl-fl\" title=\"Link to this heading\">#</a></h3><p>For an end-to-end GRPO training workflow, see <a class=\"reference internal\" href=\"../user_guide/e2e-use-case.html\"><span class=\"std std-doc\">End-to-End Use Case</span></a>.</p>", "a[href=\"#nvidia\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">NVIDIA<a class=\"headerlink\" href=\"#nvidia\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
